def factorial_zero_preimage_size(k):
    def zeros(value):
        answer=0
        while value:value//=5;answer+=value
        return answer
    def lower(target):
        left,right=0,5*target+5
        while left<right:
            middle=(left+right)//2
            if zeros(middle)>=target:right=middle
            else:left=middle+1
        return left
    return lower(k+1)-lower(k)

